    'not-applicable',
    'invalid_parent_rollup',
    'stale_parent_rollup',
    'migration_needed',
    'evaluateParentRoadmapLedger',
    'evaluateParentRoadmapClaim',
    'evaluateParentRoadmapProofStoryBinding',
    'parent_roadmap_summary_overclaim',
    'runtime implementation',
    'B-43de',
